begin;
create extension if not exists pgtap with schema extensions;
select plan(18);
insert into auth.users(id,email,raw_user_meta_data,is_sso_user,is_anonymous) values
('11111111-1111-4111-8111-111111111111','owner@example.com','{}',false,false),
('22222222-2222-4222-8222-222222222222','member@example.com','{}',false,false);
set local role service_role;
select public.mirai_bootstrap_owner('11111111-1111-4111-8111-111111111111');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select public.mirai_request_access();
select throws_ok($$select public.mirai_begin_access_email('approval','22222222-2222-4222-8222-222222222222','member@example.com',repeat('a',64))$$,'42501','owner access required','members cannot initiate email');
select is((select count(*) from public.access_email_deliveries),0::bigint,'members cannot read receipts');
select throws_ok($$select public.mirai_finish_access_email('any','11111111-1111-4111-8111-111111111111','sent','provider')$$,'42501','owner access required','members cannot forge delivery');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
create temp table request as select id from public.access_requests where requester_id='22222222-2222-4222-8222-222222222222';
select throws_ok($$select public.mirai_begin_access_email('approval',(select id from request),'member@example.com',repeat('a',64))$$,'42501','email target is unavailable','unapproved requests cannot send');
select public.mirai_decide_access((select id from request),'approve');
select throws_ok($$select public.mirai_begin_access_email('approval',(select id from request),'other@example.com',repeat('a',64))$$,'42501','email target is unavailable','recipient must match the approved profile');
create temp table claimed as select public.mirai_begin_access_email('approval',(select id from request),'member@example.com',repeat('a',64)) as receipt;
select is((select receipt->>'status' from claimed),'send','owner claims one email');
select is(public.mirai_begin_access_email('approval',(select id from request),'member@example.com',repeat('a',64))->>'status','busy','concurrent sends are blocked');
select throws_ok($$select public.mirai_finish_access_email((select receipt->>'event_key' from claimed),'11111111-1111-4111-8111-111111111111','sent','provider')$$,'40001','email attempt is no longer current','stale completion is fenced');
select public.mirai_finish_access_email((select receipt->>'event_key' from claimed),(select (receipt->>'attempt_id')::uuid from claimed),'unknown');
create temp table retry as select public.mirai_begin_access_email('approval',(select id from request),'member@example.com',repeat('a',64)) as receipt;
select is((select receipt->>'delivery_id' from retry),(select receipt->>'delivery_id' from claimed),'uncertain retry retains provider idempotency');
select public.mirai_finish_access_email((select receipt->>'event_key' from retry),(select (receipt->>'attempt_id')::uuid from retry),'sent','provider-id');
select is(public.mirai_begin_access_email('approval',(select id from request),'member@example.com',repeat('b',64))->>'status','sent','sent receipt suppresses later duplicate sends');
create temp table invite as select * from public.mirai_create_invitation('invitee@example.com');
select throws_ok($$select public.mirai_begin_access_email('invitation',(select invitation_id from invite),'invitee@example.com',repeat('a',64),repeat('b',64))$$,'42501','email target is unavailable','wrong invitation token cannot send');
create temp table invited as select public.mirai_begin_access_email('invitation',(select invitation_id from invite),'invitee@example.com',repeat('a',64),(select invite_token from invite)) as receipt;
select is((select receipt->>'status' from invited),'send','valid invitation can send');
select ok(position((select invite_token from invite) in (select receipt->>'event_key' from invited))=0,'receipt never stores the raw invitation token');
select public.mirai_finish_access_email((select receipt->>'event_key' from invited),(select (receipt->>'attempt_id')::uuid from invited),'unknown');
select is(public.mirai_begin_access_email('invitation',(select invitation_id from invite),'invitee@example.com',repeat('b',64),(select invite_token from invite))->>'status','unknown','changed message cannot repurchase uncertain delivery');
reset role;
update public.access_email_deliveries set first_attempt_at=now()-interval '25 hours' where kind='invitation';
set local role authenticated;
select is(public.mirai_begin_access_email('invitation',(select invitation_id from invite),'invitee@example.com',repeat('a',64),(select invite_token from invite))->>'status','unknown','old uncertain sends require operator reconciliation');
reset role;
update public.invitations set created_at=now()-interval '15 days', expires_at=now()-interval '1 minute' where id=(select invitation_id from invite);
set local role authenticated;
select throws_ok($$select public.mirai_begin_access_email('invitation',(select invitation_id from invite),'invitee@example.com',repeat('a',64),(select invite_token from invite))$$,'42501','email target is unavailable','expired invitation cannot send');
reset role;
select is((select count(*) from public.account_allowance_grants where account_id='22222222-2222-4222-8222-222222222222'),1::bigint,'email retry never changes credit grants');
delete from auth.users where id='22222222-2222-4222-8222-222222222222';
select is((select count(*) from public.access_email_deliveries where kind='approval'),0::bigint,'account deletion removes associated receipts');
select * from finish();
rollback;
